import pytest
from unittest.mock import patch
from isort.parse import file_contents
from isort.settings import Config
from isort.exceptions import MissingSection

def test_file_contents_comprehensive():
    content = (
        "# isort:imports-CUSTOM\n"
        "# isort: imports-CUSTOM2\n"
        "import os, sys; import math as m\n"
        "from typing import (Any, \n"
        "                    Union # type comment\n"
        "                    )\n"
        "from .local import name as local_name # local comment\n"
        "import a as a # redundant alias\n"
        "x = 1\n"
    )
    
    config = Config(
        sections=["FIRSTPARTY", "LOCALFOLDER", "CUSTOM", "CUSTOM2", "THIRDPARTY", "STANDARD_LIBRARY"],
        float_to_top=True,
        verbose=True,
        only_modified=False,
        remove_redundant_aliases=True,
        force_single_line=True,
    )
    
    parsed = file_contents(content, config=config)
    assert parsed.import_index >= 0
    assert "CUSTOM" in parsed.place_imports
    assert "CUSTOM2" in parsed.place_imports

def test_file_contents_edge_cases_and_warnings():
    content = (
        "import unplaceable_mod_xyz \\\n"
        "    as umod\n"
    )
    config = Config(sections=["KNOWN"])
    
    with patch("isort.place.module", return_value=""):
        parsed = file_contents(content, config=config)
        assert "" in parsed.imports

    with patch("isort.place.module", return_value="UNKNOWN_SECTION"):
        with pytest.raises(MissingSection):
            file_contents("import foo\n", config=Config(sections=["KNOWN"]))

def test_file_contents_trailing_comma_and_straight_comments():
    content = (
        "# Above comment\n"
        "from module import (\n"
        "    item1,\n"
        ")\n"
        "import straight_mod # straight comment\n"
    )
    config = Config(sections=["DEFAULT", "THIRDPARTY"])
    parsed = file_contents(content, config=config)
    assert "module" in parsed.trailing_commas
